using Event = std::variant<OrderPlaced, AddressChanged>;   // the closed event contract

struct Bus {
    std::vector<std::function<void(const Event&)>> subs;
    void publish(const Event& e) { for (auto& s : subs) s(e); }
};

bus.publish(OrderPlaced{.order_id = 42});
std::visit(overloaded{
    [](const OrderPlaced& e)    { index.upsert(e.order_id); },
    [](const AddressChanged& e) { cache.invalidate(e.customer_id); },
}, event);

